async fn qualification_prepare_quarantines_expired_registry_attempt_with_h7_evidence() {
    let fixture = runtime_fixture();
    attach_runtime_prerequisites(&fixture).await;
    fixture
        .registry
        .compare_and_transition(
            &fixture.identity.agent_id,
            /*expected_generation*/ 1,
            AgentLifecycle::Running,
        )
        .expect("running generation");
    fixture.state.refresh_generation().expect("refresh running");
    fixture
        .state
        .mark_app_server_ready()
        .expect("mark App Server ready");

    let store = Arc::new(
        CognitiveStore::open(&fixture.identity.layout)
            .await
            .expect("open cognitive store"),
    );
    let fleet_generation = fixture
        .state
        .qualification_turn_authority()
        .expect("qualification authority");
    let turn_id = "turn:agentd-expired-terminal";
    let spawn_generation = fixture.identity.spawn_generation;
    let logical = LogicalTurnRequest::new(
        format!("qualification:logical:{turn_id}"),
        "qualification:local",
        Sha256Digest::for_bytes(format!("qualification:logical-binding:v1:{turn_id}").as_bytes()),
    )
    .expect("logical request");
    // The real bound writes must finish while the setup lease is live. Expiry
    // is exercised afterward against its actual deadline, not a setup race.
    const SETUP_LEASE_TTL_SECONDS: u64 = 30;
    let expires_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock")
        .as_secs()
        .checked_add(SETUP_LEASE_TTL_SECONDS)
        .expect("setup lease expiry");
    let old = LogicalTurnAttemptRequest::new(
        "seed-terminal-attempt",
        "seed-terminal-lease",
        "seed-terminal-journal",
        "seed-terminal-trajectory",
        "seed-terminal-occurrence",
        /*authority_epoch*/ 1,
        fleet_generation,
        /*generation*/ 1,
        "seed-terminal-fence",
        expires_at,
    )
    .expect("terminal attempt request");
    let reservation = store
        .reserve_or_replay_logical_turn(logical, old)
        .await
        .expect("seed registry attempt");
    let codex_hepta_memory::LogicalTurnReservation::Acquired { attempt } = reservation else {
        panic!("seed must acquire registry attempt")
    };
    let head = store
        .inspect_local_lease_head(&attempt.lease_id)
        .await
        .expect("inspect seeded head")
        .head
        .expect("seeded head");
    let lease = store
        .reopen_host_bound_lease(
            head,
            attempt.authority_epoch,
            attempt.owner_epoch,
            attempt.lease_expires_at_unix_seconds,
        )
        .await
        .expect("reopen seeded lease");
    let fence = CompactFence::new(
        attempt.authority_epoch,
        attempt.owner_epoch,
        attempt.generation,
        attempt.fencing_token.clone(),
    )
    .expect("compact fence");
    let executor = store
        .open_local_compact_executor_bound(attempt.journal_id.clone(), fence, &lease)
        .await
        .expect("open compact executor");
    let binding =
        LocalTurnLifecycleBinding::from_handles(turn_id, &lease, &executor).expect("binding");
    let payload = r#"{"schema_version":1,"external_effect":false,"kg_write_authority":false,"production_caller":false}"#;
    let receipt = match lease
        .admit(
            attempt.occurrence_key.clone(),
            "codex.turn.qualification.start.v1",
            payload,
        )
        .await
        .expect("admit local intent")
    {
        LocalAdmission::Queued(receipt) | LocalAdmission::Replay(receipt) => receipt,
    };
    let trajectory_id = attempt.trajectory_id.clone();
    let start = H7TrajectoryRecord::new(
        trajectory_id.clone(),
        /*event_seq*/ 1,
        format!("{trajectory_id}:event:turn-start"),
        H7TrajectoryEventKind::TurnStart,
        turn_id,
        attempt.occurrence_key.clone(),
        /*causal_parent_seq*/ None,
        /*causal_parent_sha256*/ None,
        Sha256Digest::for_bytes(payload.as_bytes()),
        Sha256Digest::for_bytes(b"qualification:observation-only-policy:v1"),
        Sha256Digest::for_bytes(b"qualification:model-receipt:not-applicable:v1"),
        h7_trajectory_local_receipt_digest(&receipt),
        "turn_started",
        /*reward_bps*/ 0,
        /*safety_ok*/ true,
        r#"{"source":"qualification_turn_writer"}"#,
        "not_applicable",
    )
    .expect("start trajectory");
    let H7TrajectoryAppend::Inserted {
        event_sha256: parent,
        ..
    } = append_h7_trajectory_event_bound(&lease, &executor, &binding, &start)
        .await
        .expect("append H7 start")
    else {
        panic!("start must be inserted")
    };
    let terminal = H7TrajectoryRecord::terminal(
        trajectory_id.clone(),
        /*event_seq*/ 2,
        format!("{trajectory_id}:event:terminal:stop"),
        turn_id,
        format!("{}:terminal", attempt.occurrence_key),
        /*causal_parent_seq*/ 1,
        parent,
        Sha256Digest::for_bytes(b"terminal-state"),
        Sha256Digest::for_bytes(b"qualification:observation-only-policy:v1"),
        Sha256Digest::for_bytes(b"qualification:model-receipt:not-applicable:v1"),
        Sha256Digest::for_bytes(b"terminal-receipt"),
        "turn_stopped",
        "turn_stopped",
        r#"{"source":"qualification_turn_writer","terminal_action":"stop"}"#,
    )
    .expect("terminal trajectory");
    append_h7_trajectory_event_bound(&lease, &executor, &binding, &terminal)
        .await
        .expect("append H7 terminal");
    lease
        .verify_current()
        .await
        .expect("bound H7 setup must complete under a live lease");
    drop(binding);
    drop(executor);
    drop(lease);
    let remaining = (UNIX_EPOCH + Duration::from_secs(expires_at))
        .duration_since(SystemTime::now())
        .unwrap_or_default();
    tokio::time::sleep(remaining).await;
    let expired = store
        .inspect_local_lease_head(&attempt.lease_id)
        .await
        .expect("inspect expired fixture head");
    assert_eq!(
        expired.disposition,
        LocalLeaseHeadDisposition::ExpiredActive,
        "qualification prepare must observe an already-expired active head"
    );

    let result = prepare_qualification_turn_writer_input(
        Arc::clone(&fixture.state),
        Arc::clone(&store),
        fixture.identity.agent_id.clone(),
        spawn_generation,
        turn_id.to_string(),
    )
    .await;
    assert!(
        result.is_err(),
        "terminal recovery returns no writable input"
    );
    let inspected = store
        .inspect_local_lease_head(&attempt.lease_id)
        .await
        .expect("inspect recovered head");
    assert_eq!(
        inspected.disposition,
        LocalLeaseHeadDisposition::ExpiredActive,
        "registry-backed H7 quarantine must not mutate the active registry head"
    );
    assert_eq!(
        inspected, expired,
        "quarantine must preserve the exact head"
    );
}

async fn caller_abort_after_core_started_keeps_exact_authority_until_persistence()
-> anyhow::Result<()> {
    let server = start_mock_server().await;
    let response =
        responses::mount_sse_once(&server, responses::sse_completed("one-cancel-safe-owner")).await;
    let test = test_codex()
        .with_pre_build_hook(write_blocking_prompt_hook)
        .with_config(trust_discovered_hooks)
        .with_config(|config| config.include_environment_context = false)
        .build_with_auto_env(&server)
        .await?;
    let thread_id = test.session_configured.thread_id;
    let primary_runtime = test.codex.state_db().context("state runtime unavailable")?;
    let competing_runtime = StateRuntime::init(
        primary_runtime.sqlite().clone(),
        "test-provider".to_string(),
    )
    .await?;
    let owner_queue: Arc<dyn QueueStore> =
        Arc::new(FailDeleteOnceQueueStore::with_short_dispatch_lease(
            LocalQueueStore::new(Arc::clone(&primary_runtime)),
        ));
    let competing_queue: Arc<dyn QueueStore> = Arc::new(LocalQueueStore::new(competing_runtime));
    let owner = Arc::new(QueuedItemService::new(
        Arc::clone(&owner_queue),
        Arc::downgrade(&test.thread_manager),
        Arc::new(NoopExtensionEventSink),
    ));
    let competitor = QueuedItemService::new(
        competing_queue,
        Arc::downgrade(&test.thread_manager),
        Arc::new(NoopExtensionEventSink),
    );
    let input = structured_user_input("delay exact persistence");
    let TurnInput::UserInput { content, .. } = &input else {
        unreachable!("test input is user input");
    };
    let digest = user_input_payload_sha256(content)?;
    let admitted = owner
        .reconcile(
            thread_id,
            test.codex.rollout_path(),
            input,
            digest,
            QueueReconcileMode::AllowIfAbsent,
        )
        .await?;
    let QueueReconcileOutcome::Queued { item, .. } = admitted.outcome else {
        anyhow::bail!("exact Matrix input was not queued");
    };

    let owner_start = tokio::spawn({
        let owner = Arc::clone(&owner);
        let codex = Arc::clone(&test.codex);
        let queued_item_id = item.id.clone();
        async move {
            owner
                .start(codex.as_ref(), Some(queued_item_id), None)
                .await
        }
    });
    let entered = test
        .codex_home_path()
        .join("queue_blocking_prompt_hook.entered");
    let release = test
        .codex_home_path()
        .join("queue_blocking_prompt_hook.release");
    wait_for_path(&entered).await?;
    owner_start.abort();
    let aborted = owner_start
        .await
        .expect_err("caller task must be cancelled");
    assert!(aborted.is_cancelled());

    tokio::time::sleep(Duration::from_millis(400)).await;
    let competing = competitor
        .start(test.codex.as_ref(), Some(item.id.clone()), None)
        .await
        .expect_err("expired SQLite time alone must not bypass the owned process lock");
    assert!(matches!(
        competing,
        QueueServiceError::DispatchInProgress { .. }
    ));
    assert_eq!(0, response.requests().len());

    fs::write(&release, b"release")?;
    wait_for_event_match(test.codex.as_ref(), |event| {
        matches!(event, EventMsg::TurnComplete(_)).then_some(())
    })
    .await;
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            if competitor
                .list(thread_id)
                .await
                .is_ok_and(|items| items.is_empty())
            {
                return;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await?;
    assert_eq!(1, response.requests().len());
    assert_eq!(
        1,
        persisted_client_message_count(test.codex.as_ref(), "stable-client-message").await?
    );
    Ok(())
}

async fn completion_panic_retains_exact_authority_in_settlement_guardian() -> anyhow::Result<()> {
    let server = start_mock_server().await;
    let response =
        responses::mount_sse_once(&server, responses::sse_completed("panic-safe-owner")).await;
    let test = test_codex()
